<script>
(function () {
  var LINKS = window.__KK_OFFER_LINKS || {};
  var ORDER = {"monthly": ["creatormonthly", "premiummonthly", "promaxmonthly", "agencymonthly"], "yearly": ["creatoryearly", "premiumyearly", "promaxyearly", "agencyyearly"]};
  var root = document.querySelector('[data-checkout-prototype="plans-pick-your-plan"]');
  if (!root) return;

  function currentPeriod() {
    var sw = root.querySelector('.pyp-switch');
    return (sw && sw.classList.contains('on')) ? 'yearly' : 'monthly';
  }

  function wireCtas() {
    if (!LINKS || !ORDER) return;
    var period = currentPeriod();
    var grid = root.querySelector('.pyp-grid[data-period="' + period + '"]');
    if (!grid) return;
    var toks = ORDER[period] || [];
    var cols = grid.querySelectorAll('.pcol');
    cols.forEach(function (col, i) {
      var btn = col.querySelector('.pcol-cta');
      var tok = toks[i];
      if (!btn || !tok || !LINKS[tok] || LINKS[tok] === '#') return;
      if (btn.tagName === 'A') { btn.href = LINKS[tok]; }
      else { btn.onclick = function () { window.location.href = LINKS[tok]; }; }
    });
  }

  function applyPeriod(period) {
    var sw = root.querySelector('.pyp-switch');
    if (sw) sw.classList.toggle('on', period === 'yearly');
    var labs = root.querySelectorAll('.pyp-billing .lab');
    if (labs[0]) labs[0].classList.toggle('on', period === 'monthly');
    if (labs[1]) labs[1].classList.toggle('on', period === 'yearly');
    root.querySelectorAll('.pyp-grid[data-period]').forEach(function (g) {
      g.hidden = (g.getAttribute('data-period') !== period);
    });
    wireCtas();
  }

  var billing = root.querySelector('.pyp-billing');
  if (billing) {
    billing.addEventListener('click', function (e) {
      if (e.target.closest('.pyp-switch') || e.target.closest('.lab')) {
        applyPeriod(currentPeriod() === 'yearly' ? 'monthly' : 'yearly');
      }
    });
  }

  root.addEventListener('click', function (e) {
    var q = e.target.closest('.faq-q');
    if (q) {
      var item = q.closest('.faq-item');
      if (item) item.classList.toggle('open');
    }
  });

  (function initCountdown() {
    var row = root.querySelector('.promo-clock-row');
    if (!row) return;
    var nums = row.querySelectorAll('.promo-num');
    if (nums.length < 4) return;
    var KEY = 'aipu_promo_deadline_7d';
    var now = Date.now();
    var dl = parseInt(localStorage.getItem(KEY) || '0', 10);
    if (!dl || dl < now || dl > now + 6048e5) {
      dl = now + 6048e5;
      try { localStorage.setItem(KEY, String(dl)); } catch (e) {}
    }
    function pad(n) { return String(n).padStart(2, '0'); }
    function tick() {
      var d = Math.max(0, dl - Date.now());
      nums[0].textContent = pad(Math.floor(d / 864e5));
      nums[1].textContent = pad(Math.floor((d % 864e5) / 36e5));
      nums[2].textContent = pad(Math.floor((d % 36e5) / 6e4));
      nums[3].textContent = pad(Math.floor((d % 6e4) / 1e3));
    }
    tick();
    setInterval(tick, 1000);
  })();
  applyPeriod('monthly');
})();
</script>
